-- Seed the product service inventory as inactive. Configure price, coverage, SLA,
-- skills and operational requirements before an administrator activates each service.
-- Existing catalogue and historical IDs are preserved by the conflict-safe inserts.
UPDATE service_eligibility_rules r
SET rule_name='ALL_PROPERTY_TYPES',
    rule_definition='{"field":"PROPERTY_TYPE","operator":"IN","value":["HOUSE","VILLA","APARTMENT","TOWNHOUSE","COMMERCIAL_PROPERTY","INDUSTRIAL_PROPERTY","PLOT","AGRICULTURAL_LAND","OTHER"]}'::jsonb,
    updated_at=CURRENT_TIMESTAMP
FROM services s
WHERE r.service_id=s.service_id
  AND s.service_code='DOCUMENT_PROCUREMENT'
  AND r.rule_name='PROPERTY_TYPE_APARTMENT'
  AND r.status='ACTIVE';

CREATE TEMPORARY TABLE propertypilot_service_seed (
  service_code VARCHAR(80) PRIMARY KEY,
  service_name VARCHAR(255) NOT NULL,
  category VARCHAR(100) NOT NULL,
  property_types TEXT[] NOT NULL
) ON COMMIT DROP;

;

SELECT service_code, service_name, category, 0, FALSE
FROM propertypilot_service_seed
ON CONFLICT (service_code) DO NOTHING;

SELECT gen_random_uuid(), s.service_id, 'PROPERTY_TYPE_COVERAGE',
       jsonb_build_object('field','PROPERTY_TYPE','operator','IN','value',seed.property_types), 100, 'ACTIVE'
FROM propertypilot_service_seed seed
JOIN services s ON s.service_code=seed.service_code
ON CONFLICT (service_id, rule_name) DO NOTHING;
